CREATE OR REPLACE FUNCTION public.validate_maintenance_closure_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.status = 'Concluída' AND OLD.status IS DISTINCT FROM 'Concluída' THEN IF NEW.finished_at IS NULL OR NOT EXISTS (SELECT 1 FROM public.op_maintenance_photos WHERE maintenance_order_id = NEW.id AND photo_type = 'depois') THEN RAISE EXCEPTION 'Data/hora e foto de finalização são obrigatórias'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER maintenance_closure_evidence BEFORE UPDATE ON public.op_maintenance_orders FOR EACH ROW EXECUTE FUNCTION public.validate_maintenance_closure_evidence();